mapper.select:
select message_id as messageId, revision_no as revisionNo, check_status as checkStatus, content
  from im_message_revision
 where message_id = #{messageId}
 and revision_no < #{before}
 order by revision_no desc limit #{limit}

select message_id from im_message_pin
 where conversation_id = #{conversationId}
   and message_id in #{i}

select m.id from im_message m
 where m.conversation_id = #{conversationId} and  and m.msg_type = 1
   and m.content like concat('%', #{keyword}, '%') escape '!'
   and m.create_time >= #{from}
   and m.create_time < #{to}
   and m.sender_id = #{authorId}
   and m.id < #{before}
 order by m.id desc limit #{limit}
